INSERT INTO public.posts (id, content, status, published_at, title)
VALUES ('21fa97ea-d7ff-5e36-a305-dc308cbe899b', '[{"type":"heading","props":{"level":1},"content":"[Demo] A small plan for next spring"},{"type":"paragraph","content":"This is sample writing for the public archive. Dates, year groups, character totals, and visibility come from the stored content."},{"type":"heading","props":{"level":2},"content":"A place to begin"},{"type":"paragraph","content":"A small project can be useful long before it feels finished. Begin with one thing that matters, make it work, and leave the next step clear enough to find tomorrow."},{"type":"heading","props":{"level":2},"content":"What I want to remember"},{"type":"paragraph","content":[{"type":"text","text":"Keep the important parts simple.","styles":{"bold":true}},{"type":"text","text":" The rest can change as we learn more.","styles":{}}]},{"type":"paragraph","content":"A record does not need to capture everything. A few honest details are enough to help us remember where we started."}]'::jsonb, 'show', '2027-03-21T08:00:00Z', '[Demo] A small plan for next spring')
ON CONFLICT (id) DO NOTHING;

